import re


def slugify(text):
    text = text.strip().lower()
    # Replace non-alphanumeric characters with hyphens, but preserve apostrophes
    result = []
    for char in text:
        if char in "':-":  # Allow apostrophes and special chars
            result.append(char)
        else:
            result.append('-')
    return ''.join(result)


